package com.crossdrop.core

import com.crossdrop.core.i18n.I18n
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.jsonObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Every shipped language has every string (`tools/l10n/source/en.json`, regenerated by
 * `python3 tools/l10n/l10n.py extract`), with the same placeholders and the plural forms its language needs.
 */
class L10nCatalogTest {
    private val root = generateSequence(File("").absoluteFile) { it.parentFile }.first { File(it, "l10n").isDirectory }
    private val en: JsonObject = Json.parseToJsonElement(File(root, "tools/l10n/source/en.json").readText()).jsonObject
    private val languages = I18n.supported - "en"

    private val pluralForms = mapOf(
        "ka" to setOf("one", "other"), "hi" to setOf("one", "other"), "id" to setOf("other"),
        "ar" to setOf("zero", "one", "two", "few", "many", "other"), "fa" to setOf("one", "other"),
        "es" to setOf("one", "other"), "pt" to setOf("one", "other"),
        "ru" to setOf("one", "few", "many", "other"), "tr" to setOf("one", "other"),
    )

    private fun placeholders(s: String) = Regex("""\{(?:n|\d+)}""").findAll(s).map { it.value }.sorted().toList()

    private fun catalog(lang: String): JsonObject {
        val file = File(root, "l10n/$lang.json")
        assertTrue("l10n/$lang.json is missing", file.isFile)
        return Json.parseToJsonElement(file.readText()).jsonObject
    }

    @Test fun `every language has every string`() {
        for (lang in languages) {
            val missing = en.keys - catalog(lang).keys
            assertTrue("$lang is missing ${missing.size} strings, e.g. ${missing.take(5)}", missing.isEmpty())
        }
    }

    @Test fun `placeholders survive translation`() {
        for (lang in languages) {
            val cat = catalog(lang)
            for ((key, source) in en) {
                val value = cat[key] ?: continue
                if (source is JsonPrimitive) {
                    val text = (value as? JsonPrimitive)?.content.orEmpty()
                    assertTrue("$lang: '$key' is empty", text.isNotBlank())
                    assertEquals("$lang: placeholders of '$key' in '$text'", placeholders(key), placeholders(text))
                }
            }
        }
    }

    @Test fun `plural entries have the forms their language needs`() {
        for (lang in languages) {
            val cat = catalog(lang)
            for ((key, source) in en) {
                if (source !is JsonObject) continue
                val forms = (cat[key] as? JsonObject)
                assertTrue("$lang: '$key' must be a plural object", forms != null)
                val have = forms!!.filterValues { (it as? JsonPrimitive)?.content?.isNotBlank() == true }.keys
                assertEquals("$lang: plural forms of '$key'", pluralForms.getValue(lang), have)
                val allowed = placeholders(key).toSet()
                for ((cat2, text) in forms) {
                    val extra = placeholders((text as JsonPrimitive).content).toSet() - allowed
                    assertTrue("$lang: '$key' [$cat2] has unknown placeholders $extra", extra.isEmpty())
                }
            }
        }
    }

    @Test fun `no catalog carries strings the code no longer has`() {
        for (lang in languages) {
            val stale = catalog(lang).keys - en.keys
            assertTrue("$lang has stale strings: ${stale.take(5)}", stale.isEmpty())
        }
    }
}
